import{_ as a,o as r,c as t,a7 as i,as as l,av as s}from"./chunks/framework.DLZEy9Ii.js";const g=JSON.parse('{"title":"音乐分享","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"share.md","filePath":"share.md"}'),o={name:"share.md"};function d(n,e,h,c,_,m){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="音乐分享" tabindex="-1">音乐分享 <a class="header-anchor" href="#音乐分享" aria-label="Permalink to “音乐分享”">​</a></h1><p>相关文档：<a href="/music-free-site/serve.html">MusicFreeServe 集成</a> · <a href="/music-free-site/playlist.html">歌单</a> · <a href="/music-free-site/user.html">用户</a></p><h2 id="_1-模块概述" tabindex="-1">1. 模块概述 <a class="header-anchor" href="#_1-模块概述" aria-label="Permalink to “1. 模块概述”">​</a></h2><p><strong>音乐分享</strong>允许把本地曲库中的<strong>歌曲或歌单</strong>分享出去，供其他用户直接下载并自动入库；也可下载他人分享的音乐。该能力默认关闭，需在「用户配置」中显式开启，并与 <a href="/music-free-site/serve.html">MusicFreeServe 集成</a> 配合完成节点引导。</p><h2 id="_2-开启与前置条件" tabindex="-1">2. 开启与前置条件 <a class="header-anchor" href="#_2-开启与前置条件" aria-label="Permalink to “2. 开启与前置条件”">​</a></h2><ol><li>在「用户配置」中完成 MusicFreeServe 的地址与 API Key 配置并启用；</li><li>在「用户配置 → <strong>音乐分享</strong>」卡片中打开开关；</li><li><strong>Docker 部署必须使用 host 网络模式（<code>network_mode: host</code>）</strong>，否则分享节点无法正常发现与连接；飞牛原生应用不受影响。</li></ol><p>开启后，卡片会显示节点状态、链路状态与网络观测，并支持一键刷新。</p><p><img src="'+l+'" alt=""></p><h2 id="_3-分享-发布方" tabindex="-1">3. 分享（发布方） <a class="header-anchor" href="#_3-分享-发布方" aria-label="Permalink to “3. 分享（发布方）”">​</a></h2><h3 id="_3-1-分享歌曲-歌单" tabindex="-1">3.1 分享歌曲 / 歌单 <a class="header-anchor" href="#_3-1-分享歌曲-歌单" aria-label="Permalink to “3.1 分享歌曲 / 歌单”">​</a></h3><ul><li>在「音乐分享」卡片搜索本地歌曲，或多选后点击「分享所选歌曲」；</li><li>也可直接选择一张歌单进行分享；</li><li>分享记录持久化，进程重启或链路重连后自动恢复。</li></ul><p><img src="'+s+'" alt=""></p><h3 id="_3-2-歌单分享与文件标识" tabindex="-1">3.2 歌单分享与文件标识 <a class="header-anchor" href="#_3-2-歌单分享与文件标识" aria-label="Permalink to “3.2 歌单分享与文件标识”">​</a></h3><p>在歌单详情的「共享」弹窗中勾选「分享歌曲」后：</p><ul><li>歌单内歌曲会作为分享内容发布；</li><li>歌单同步到 serve 时，每条曲目会附带<strong>文件标识（哈希）</strong>，订阅方据此可直接下载；</li><li>关闭勾选或关闭共享会撤回该歌单的分享。</li></ul><h3 id="_3-3-撤回" tabindex="-1">3.3 撤回 <a class="header-anchor" href="#_3-3-撤回" aria-label="Permalink to “3.3 撤回”">​</a></h3><p>在分享列表中点击「撤回」会撤销发布并删除记录，<strong>不会删除本地文件</strong>。</p><h2 id="_4-下载-接收方" tabindex="-1">4. 下载（接收方） <a class="header-anchor" href="#_4-下载-接收方" aria-label="Permalink to “4. 下载（接收方）”">​</a></h2><ul><li>在「音乐分享」卡片的下载区输入<strong>文件标识</strong>（可附文件名）→「下载到音乐库」；</li><li>在<strong>共享歌单详情</strong>页，可对携带文件标识的曲目逐曲下载，或在标题栏「全部下载」批量加入队列；</li><li>下载固定落入默认音乐库 <code>music.library_path</code>，完成后自动触发扫描入库，并成为新的分享来源。</li></ul><h3 id="_4-1-自动重试" tabindex="-1">4.1 自动重试 <a class="header-anchor" href="#_4-1-自动重试" aria-label="Permalink to “4.1 自动重试”">​</a></h3><ul><li>下载失败的任务会<strong>自动重新入队</strong>，单首最多重试 <strong>3 次</strong>（不含首次）；</li><li>也可在界面<strong>手动重试</strong>（手动重试会重置自动重试预算）；</li><li>达到上限后保持 <code>failed</code>，可稍后重试。</li></ul><h2 id="_5-约束" tabindex="-1">5. 约束 <a class="header-anchor" href="#_5-约束" aria-label="Permalink to “5. 约束”">​</a></h2><table tabindex="0"><thead><tr><th>约束</th><th>说明</th></tr></thead><tbody><tr><td>音乐源</td><td>本地源直接分享；WebDAV 等远程源会先缓存到本地再发布</td></tr><tr><td>音频格式</td><td>mp3 / flac / wav / ogg / opus / m4a / aac / wma（按内容嗅探，与扩展名无关）</td></tr><tr><td>单文件上限</td><td>200 MiB</td></tr><tr><td>不覆盖</td><td>目标同名且内容不同的文件会被拒绝覆盖</td></tr><tr><td>网络</td><td>部分网络环境（如对称 NAT / CGNAT）打洞可能失败，属预期情况</td></tr></tbody></table><h2 id="_6-常见问题" tabindex="-1">6. 常见问题 <a class="header-anchor" href="#_6-常见问题" aria-label="Permalink to “6. 常见问题”">​</a></h2><p><strong>Q：开启后提示需要先配置 MusicFreeServe？</strong><br> A：音乐分享依赖 serve 进行节点引导，请先在「用户配置」完成 MusicFreeServe 配置。</p><p><strong>Q：Docker 部署后分享不可用？</strong><br> A：请改用 host 网络模式（<code>network_mode: host</code>）后重启，并确保出网能力正常。</p><p><strong>Q：下载很慢或失败？</strong><br> A：可能是分享方离线或处于不支持打洞的网络环境，可稍后重试；下载任务会自动重试。</p>',27)])])}const b=a(o,[["render",d]]);export{g as __pageData,b as default};
